//! Numbers and dates written and read the way the .NET 0.4.3 code does.
//!
//! `System.Text.Json` writes a double with its shortest round-trip digits in its own layout, and
//! a `DateTimeOffset` as ISO 8601 with a trimmed fraction. The fixed formats of the daemon, the
//! log and the backups, and `Math.Round(x, 6)`, are reproduced here too. Everything is checked
//! row by row against `rust/tests/golden/formats.json` (`tests/formats_golden.rs`), generated by
//! `rust/tools/format-oracle`.

use std::fmt::Write as _;
use std::time::{SystemTime, UNIX_EPOCH};

const TICKS_PER_SECOND: i64 = 10_000_000;
const TICKS_PER_MINUTE: i64 = 60 * TICKS_PER_SECOND;
const TICKS_PER_DAY: i64 = 86_400 * TICKS_PER_SECOND;
/// `DateTime.MaxValue.Ticks`: 9999-12-31T23:59:59.9999999.
const MAX_TICKS: i64 = 3_155_378_975_999_999_999;
/// Days from 0001-01-01 to 1970-01-01.
const DAYS_TO_UNIX_EPOCH: i64 = 719_162;
/// `DateTimeOffset` offsets are limited to ±14:00.
const MAX_OFFSET_MINUTES: i16 = 14 * 60;

/// The text `System.Text.Json` writes for a double.
///
/// Digits are the shortest that round-trip (as `{:e}` gives them). The layout is the .NET one:
/// positional notation when the decimal exponent is between -4 and 16 (`0.0001`,
/// `10000000000000000`, never `.0`), else `d.dddE+XX` / `d.dddE-XX` with at least two exponent
/// digits (`1E-05`, `1E+17`). Negative zero is `-0`.
///
/// `System.Text.Json` throws on NaN and infinity (the oracle records them with no text): this
/// function returns `None` for them and never panics.
pub fn json_double(value: f64) -> Option<String> {
    if !value.is_finite() {
        return None;
    }
    let sign = if value.is_sign_negative() { "-" } else { "" };
    if value == 0.0 {
        return Some(format!("{sign}0"));
    }
    // `{:e}` gives `d[.ddd]e<exp>`: split it into digits and decimal exponent.
    // At the shortest length, `{:e}` can break an exact tie upward (`...809.125` gives `.13`) where
    // .NET keeps the even digit (`.12`): reformat the same number of digits with the exact,
    // half-to-even rounding of a precision. For a power of two the round-trip interval is
    // asymmetric and that reformat can fall outside it, so it is kept only if it reads back as
    // the same double.
    let shortest = format!("{:e}", value.abs());
    let places = shortest
        .split_once('e')
        .map_or(0, |(m, _)| m.len().saturating_sub(2));
    let even = format!("{:.*e}", places, value.abs());
    let scientific = if even.parse::<f64>().is_ok_and(|v| v == value.abs()) {
        even
    } else {
        shortest
    };
    let (mantissa, exponent) = scientific.split_once('e').unwrap_or((&scientific, "0"));
    let exponent: i32 = exponent.parse().unwrap_or(0);
    let digits: String = mantissa.chars().filter(|c| *c != '.').collect();
    let count = i32::try_from(digits.len()).unwrap_or(i32::MAX);

    let mut out = String::from(sign);
    if (-5 < exponent) && (exponent < 17) {
        if exponent < 0 {
            // 0.000ddd
            out.push_str("0.");
            out.extend(std::iter::repeat_n(
                '0',
                usize::try_from(-exponent - 1).unwrap_or(0),
            ));
            out.push_str(&digits);
        } else if count <= exponent + 1 {
            // An integer: pad with zeros, no fraction.
            out.push_str(&digits);
            out.extend(std::iter::repeat_n(
                '0',
                usize::try_from(exponent + 1 - count).unwrap_or(0),
            ));
        } else {
            let split = usize::try_from(exponent + 1).unwrap_or(0);
            out.push_str(&digits[..split]);
            out.push('.');
            out.push_str(&digits[split..]);
        }
    } else {
        out.push_str(&digits[..1]);
        if digits.len() > 1 {
            out.push('.');
            out.push_str(&digits[1..]);
        }
        let exponent_sign = if exponent < 0 { '-' } else { '+' };
        let _ = write!(out, "E{exponent_sign}{:02}", exponent.abs());
    }
    Some(out)
}

/// `Math.Round(value, 6)` of .NET: midpoint to even.
///
/// .NET scales by 10^6, rounds to the nearest integer (ties to even), and scales back, but only
/// when `|value| < 1e16`; larger values have no fraction and are returned as they are.
pub fn round6(value: f64) -> f64 {
    if value.abs() < 1e16 {
        (value * 1e6).round_ties_even() / 1e6
    } else {
        value
    }
}

/// A `DateTimeOffset`: an instant (100-ns ticks since 0001-01-01T00:00:00 UTC, as `UtcTicks`)
/// and the offset it is displayed with, in minutes.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct DateTimeOffset {
    utc_ticks: i64,
    offset_minutes: i16,
}

/// Written as `System.Text.Json` writes a `DateTimeOffset` ([`DateTimeOffset::to_json_text`]):
/// `WriteStringValue(DateTimeOffset)` formats the text itself, without the string encoder, so
/// the `+` of the offset stays as it is. The text holds only digits and `-:T.+`, so it goes out
/// as a raw JSON string.
impl serde::Serialize for DateTimeOffset {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        let raw = serde_json::value::RawValue::from_string(format!("\"{}\"", self.to_json_text()))
            .map_err(serde::ser::Error::custom)?;
        raw.serialize(serializer)
    }
}

impl DateTimeOffset {
    /// Builds a value, or `None` where the .NET constructor throws: the offset is beyond ±14:00,
    /// or the UTC ticks or the local ticks fall outside `0..=DateTime.MaxValue.Ticks`.
    pub fn new(utc_ticks: i64, offset_minutes: i16) -> Option<Self> {
        if offset_minutes.unsigned_abs() > MAX_OFFSET_MINUTES.unsigned_abs()
            || !(0..=MAX_TICKS).contains(&utc_ticks)
        {
            return None;
        }
        let local = utc_ticks + i64::from(offset_minutes) * TICKS_PER_MINUTE;
        (0..=MAX_TICKS).contains(&local).then_some(Self {
            utc_ticks,
            offset_minutes,
        })
    }

    /// The current instant, with offset zero (precision of the system clock, in ticks).
    ///
    /// A clock before 1970 or beyond year 9999 does not panic: it falls back to the minimum
    /// instant, 0001-01-01T00:00:00Z.
    pub fn now_utc() -> Self {
        let since_epoch = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .map_or(0, |d| d.as_nanos() / 100);
        let ticks = i64::try_from(since_epoch).unwrap_or(0) + DAYS_TO_UNIX_EPOCH * TICKS_PER_DAY;
        Self::new(ticks, 0).unwrap_or(Self {
            utc_ticks: 0,
            offset_minutes: 0,
        })
    }

    /// `DateTimeOffset.Now`: the current instant with the offset of the local zone
    /// ([`local_offset_at`]).
    pub fn now_local() -> Self {
        let now = Self::now_utc();
        Self::new(now.utc_ticks, local_offset_at(now.utc_ticks)).unwrap_or(now)
    }

    /// `UtcTicks`.
    pub fn utc_ticks(&self) -> i64 {
        self.utc_ticks
    }

    /// The offset in minutes, as `(int)Offset.TotalMinutes`.
    pub fn offset_minutes(&self) -> i16 {
        self.offset_minutes
    }

    /// `Ticks`: the ticks of the local clock reading.
    pub fn local_ticks(&self) -> i64 {
        self.utc_ticks + i64::from(self.offset_minutes) * TICKS_PER_MINUTE
    }

    /// The text `System.Text.Json` writes, without the surrounding quotes:
    /// `yyyy-MM-ddTHH:mm:ss[.fffffff]zzz`, the fraction trimmed of trailing zeros and absent when
    /// zero.
    pub fn to_json_text(&self) -> String {
        let mut out = self.clock(true);
        let fraction = self.local_ticks() % TICKS_PER_SECOND;
        if fraction != 0 {
            let digits = format!("{fraction:07}");
            out.push('.');
            out.push_str(digits.trim_end_matches('0'));
        }
        out.push_str(&self.offset_text());
        out
    }

    /// The `"O"` format: always seven fraction digits.
    pub fn to_o(&self) -> String {
        let fraction = self.local_ticks() % TICKS_PER_SECOND;
        format!("{}.{fraction:07}{}", self.clock(true), self.offset_text())
    }

    /// `yyyy-MM-dd'T'HH:mm:ss.fffzzz`: milliseconds are truncated, not rounded.
    pub fn to_log(&self) -> String {
        let millis = self.local_ticks() % TICKS_PER_SECOND / 10_000;
        format!("{}.{millis:03}{}", self.clock(true), self.offset_text())
    }

    /// `yyyy-MM-dd'T'HH:mm:sszzz`.
    pub fn to_seconds(&self) -> String {
        format!("{}{}", self.clock(true), self.offset_text())
    }

    /// `yyyyMMdd'T'HHmmss'Z'`, always in UTC.
    pub fn to_backup(&self) -> String {
        let utc = Self {
            utc_ticks: self.utc_ticks,
            offset_minutes: 0,
        };
        utc.clock(false) + "Z"
    }

    /// `yyyy-MM-ddTHH:mm:ss` of the local clock; without separators (`yyyyMMddTHHmmss`) when
    /// `separators` is false.
    fn clock(&self, separators: bool) -> String {
        let local = self.local_ticks();
        let (year, month, day) = civil_from_days(local / TICKS_PER_DAY - DAYS_TO_UNIX_EPOCH);
        let seconds = local % TICKS_PER_DAY / TICKS_PER_SECOND;
        let (h, m, s) = (seconds / 3600, seconds / 60 % 60, seconds % 60);
        if separators {
            format!("{year:04}-{month:02}-{day:02}T{h:02}:{m:02}:{s:02}")
        } else {
            format!("{year:04}{month:02}{day:02}T{h:02}{m:02}{s:02}")
        }
    }

    /// `zzz`: `+HH:mm` or `-HH:mm`, `+00:00` for zero.
    fn offset_text(&self) -> String {
        let sign = if self.offset_minutes < 0 { '-' } else { '+' };
        let minutes = self.offset_minutes.unsigned_abs();
        format!("{sign}{:02}:{:02}", minutes / 60, minutes % 60)
    }
}

/// Decision A5 (chrono, decision of John of 2026-11-10), boundary of the local time zone: the
/// offset of the zone of the machine at an instant, in minutes, as
/// `TimeZoneInfo.Local.GetUtcOffset` (`DateTimeOffset.Now`, the lines of the daemon journal,
/// `registeredAt`). `rust/tests/golden/local-offset*.json` is the truth.
pub fn local_offset_at(utc_ticks: i64) -> i16 {
    guarded(|| minutes(offset_at(naive(utc_ticks)?)))
}

/// Decision A5, boundary of the local time zone: the offset .NET gives a clock reading of the
/// zone of the machine read without offset (`createdAt` of `instance.json`, stored dates read
/// by `System.Text.Json` or `DateTimeOffset.Parse`), from its local ticks. The rule, measured
/// on the oracle (`local-offset*.json`, Europe/Dublin, Africa/Casablanca and Asia/Kathmandu
/// included):
/// - a reading that one offset only gives back (the offset of the day before or of the day
///   after, whose instant has that offset) takes that offset;
/// - a reading of a repeated or a skipped hour belongs to a change. When the new offset was in
///   force within the 400 days before the change, or the old one comes back within the 400
///   days after it (a seasonal change: daylight saving time, Ramadan, the first summer of a
///   new daylight saving time as Australia/Lord_Howe in 1985), it takes the smaller of the two
///   offsets. Otherwise (a change of standard time:
///   Asia/Kathmandu in 1986, Africa/Casablanca at the end of 1985) the change splits the clock
///   where the old offset reaches it: before, the old offset; from there, the new one.
///
/// Named deviation (decision of John of 2026-11-16): the skipped hour of Europe/Moscow on
/// 2011-03-27 reads 180 here, 240 in .NET, which tells it by the daylight flag of its zone data.
pub fn local_offset_of_clock(local_ticks: i64) -> i16 {
    use chrono::{Days, TimeDelta};
    guarded(|| {
        let clock = naive(local_ticks)?;
        let old = offset_at(clock - Days::new(1))?;
        let new = offset_at(clock + Days::new(1))?;
        let instant = |offset: chrono::FixedOffset| {
            clock - TimeDelta::seconds(i64::from(offset.local_minus_utc()))
        };
        let valid = |offset| offset_at(instant(offset)) == Some(offset);
        if old == new || valid(old) != valid(new) {
            return minutes(Some(if valid(new) && (old == new || !valid(old)) {
                new
            } else {
                old
            }));
        }
        // The instant of the change: the first whole second with the new offset.
        let (mut low, mut high) = (clock - Days::new(1), clock + Days::new(1));
        while high - low > TimeDelta::seconds(1) {
            let middle = low + TimeDelta::seconds((high - low).num_seconds() / 2);
            if offset_at(middle) == Some(old) {
                low = middle;
            } else {
                high = middle;
            }
        }
        // ponytail: seasonal or not is told by daily samples over 400 days on each side, on
        // this rare path only; .NET tells it by the daylight flags of its zone data.
        let seasonal = (1..=400).any(|day| {
            offset_at(high - Days::new(day)) == Some(new)
                || offset_at(high + Days::new(day)) == Some(old)
        });
        let (old_minutes, new_minutes) = (minutes(Some(old))?, minutes(Some(new))?);
        Some(if seasonal {
            old_minutes.min(new_minutes)
        } else if clock < high + TimeDelta::seconds(i64::from(old.local_minus_utc())) {
            old_minutes
        } else {
            new_minutes
        })
    })
}

/// The `NaiveDateTime` of ticks (whole seconds).
fn naive(ticks: i64) -> Option<chrono::NaiveDateTime> {
    let seconds = (ticks - DAYS_TO_UNIX_EPOCH * TICKS_PER_DAY).div_euclid(TICKS_PER_SECOND);
    chrono::DateTime::from_timestamp(seconds, 0).map(|d| d.naive_utc())
}

/// The offset of the local zone at a UTC reading.
fn offset_at(utc: chrono::NaiveDateTime) -> Option<chrono::FixedOffset> {
    use chrono::{Local, TimeZone};
    Some(Local.offset_from_utc_datetime(&utc))
}

/// Set once chrono has panicked on the zone of the machine: chrono is not called again.
static BROKEN_ZONE: std::sync::atomic::AtomicBool = std::sync::atomic::AtomicBool::new(false);

/// A zone read through chrono never stops the process: chrono panics on a zone it cannot use
/// (an unreadable or broken zone file), where .NET falls back to UTC; so does the port, and
/// the zone is not read again, so that the panic message is printed once.
fn guarded(read: impl FnOnce() -> Option<i16>) -> i16 {
    guarded_with(&BROKEN_ZONE, read)
}

fn guarded_with(broken: &std::sync::atomic::AtomicBool, read: impl FnOnce() -> Option<i16>) -> i16 {
    use std::sync::atomic::Ordering;
    if broken.load(Ordering::Relaxed) {
        return 0;
    }
    match std::panic::catch_unwind(std::panic::AssertUnwindSafe(read)) {
        Ok(offset) => offset.unwrap_or(0),
        Err(_) => {
            broken.store(true, Ordering::Relaxed);
            0
        }
    }
}

/// Whole minutes of an offset.
// ponytail: an offset with seconds (local mean time before 1912 on Unix) is cut to its
// minutes; .NET rounds those differently (PARITY.md, Écarts assumés).
fn minutes(offset: Option<chrono::FixedOffset>) -> Option<i16> {
    i16::try_from(offset?.local_minus_utc() / 60).ok()
}

/// Civil date (year, month, day) from days since 1970-01-01 (proleptic Gregorian calendar).
fn civil_from_days(days: i64) -> (i64, i64, i64) {
    let z = days + 719_468;
    let era = z.div_euclid(146_097);
    let doe = z.rem_euclid(146_097);
    let yoe = (doe - doe / 1460 + doe / 36_524 - doe / 146_096) / 365;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let day = doy - (153 * mp + 2) / 5 + 1;
    let month = if mp < 10 { mp + 3 } else { mp - 9 };
    (yoe + era * 400 + i64::from(month <= 2), month, day)
}

/// Days since 1970-01-01 of a civil date; the inverse of [`civil_from_days`].
fn days_from_civil(year: i64, month: i64, day: i64) -> i64 {
    let y = year - i64::from(month <= 2);
    let era = y.div_euclid(400);
    let yoe = y - era * 400;
    let doy = (153 * (if month > 2 { month - 3 } else { month + 9 }) + 2) / 5 + day - 1;
    let doe = yoe * 365 + yoe / 4 - yoe / 100 + doy;
    era * 146_097 + doe - 719_468
}

fn is_leap(year: i64) -> bool {
    year % 4 == 0 && (year % 100 != 0 || year % 400 == 0)
}

/// Reads `count` ASCII digits at `*pos`, advancing it; `None` on any other byte or a short input.
fn digits(bytes: &[u8], pos: &mut usize, count: usize) -> Option<i64> {
    let chunk = bytes.get(*pos..*pos + count)?;
    *pos += count;
    chunk.iter().try_fold(0i64, |acc, b| {
        b.is_ascii_digit().then(|| acc * 10 + i64::from(b - b'0'))
    })
}

/// Consumes `byte` at `*pos` if it is there.
fn eat(bytes: &[u8], pos: &mut usize, byte: u8) -> bool {
    let found = bytes.get(*pos) == Some(&byte);
    *pos += usize::from(found);
    found
}

/// What `System.Text.Json` accepts when it reads a `DateTimeOffset` string.
///
/// Accepted: `yyyy-MM-dd`, then optionally `THH:mm`, `:ss`, and `.` followed by any number of
/// digits (only the first seven count; a bare `.` is accepted, as the oracle shows), then
/// optionally `Z` (uppercase only) or `+HH`, `+HH:mm`, `-HH`, `-HH:mm`. Refused: `+HHMM`, a space
/// instead of `T`, lowercase `t` or `z`, hour 24, second 60, impossible dates, an offset beyond
/// ±14:00, anything around the text, and values whose local or UTC reading is outside
/// 0001-01-01..9999-12-31.
///
/// Without an offset the text is read in the local time zone: `local_offset_minutes` receives
/// the local ticks and returns the offset of the machine at that time.
pub fn parse_json_text(
    text: &str,
    local_offset_minutes: impl Fn(i64) -> i16,
) -> Option<DateTimeOffset> {
    let bytes = text.as_bytes();
    let mut pos = 0;
    let year = digits(bytes, &mut pos, 4)?;
    eat(bytes, &mut pos, b'-').then_some(())?;
    let month = digits(bytes, &mut pos, 2)?;
    eat(bytes, &mut pos, b'-').then_some(())?;
    let day = digits(bytes, &mut pos, 2)?;
    let days_in_month = match month {
        1 | 3 | 5 | 7 | 8 | 10 | 12 => 31,
        4 | 6 | 9 | 11 => 30,
        2 if is_leap(year) => 29,
        2 => 28,
        _ => return None,
    };
    if year < 1 || day < 1 || day > days_in_month {
        return None;
    }
    let (mut hour, mut minute, mut second, mut fraction) = (0, 0, 0, 0);
    let mut has_time = false;
    if eat(bytes, &mut pos, b'T') {
        has_time = true;
        hour = digits(bytes, &mut pos, 2)?;
        eat(bytes, &mut pos, b':').then_some(())?;
        minute = digits(bytes, &mut pos, 2)?;
        if eat(bytes, &mut pos, b':') {
            second = digits(bytes, &mut pos, 2)?;
            if eat(bytes, &mut pos, b'.') {
                // Seven digits are ticks; further digits are read but dropped. The .NET reader
                // refuses a fraction of more than 16 digits (16 are accepted, 17 are not),
                // whatever follows, so that cap is the rule, not the total length.
                let mut kept = 0;
                let mut read = 0;
                while let Some(b) = bytes.get(pos).filter(|b| b.is_ascii_digit()) {
                    read += 1;
                    if read > 16 {
                        return None;
                    }
                    if kept < 7 {
                        fraction = fraction * 10 + i64::from(b - b'0');
                        kept += 1;
                    }
                    pos += 1;
                }
                fraction *= 10i64.pow(7 - kept);
            }
        }
        if hour > 23 || minute > 59 || second > 59 {
            return None;
        }
    }
    let local_ticks = (days_from_civil(year, month, day) + DAYS_TO_UNIX_EPOCH) * TICKS_PER_DAY
        + (hour * 3600 + minute * 60 + second) * TICKS_PER_SECOND
        + fraction;

    let offset_minutes = if !has_time || pos == bytes.len() {
        // No offset: the local time zone decides.
        local_offset_minutes(local_ticks)
    } else if eat(bytes, &mut pos, b'Z') {
        0
    } else {
        let negative = match bytes.get(pos)? {
            b'+' => false,
            b'-' => true,
            _ => return None,
        };
        pos += 1;
        let hours = digits(bytes, &mut pos, 2)?;
        let minutes = if eat(bytes, &mut pos, b':') {
            digits(bytes, &mut pos, 2)?
        } else {
            0
        };
        if minutes > 59 {
            return None;
        }
        let total = i16::try_from(hours * 60 + minutes).ok()?;
        if negative { -total } else { total }
    };
    if pos != bytes.len() {
        return None;
    }
    DateTimeOffset::new(
        local_ticks - i64::from(offset_minutes) * TICKS_PER_MINUTE,
        offset_minutes,
    )
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A zone chrono cannot use makes it panic; the boundary answers UTC instead. A broken zone
    /// of the machine cannot be forged from a test (Windows reads the registry, Unix the zone
    /// file named by `TZ`, which chrono reads once per process), so the guard itself is tested.
    #[test]
    fn a_panicking_zone_reads_as_utc() {
        let broken = std::sync::atomic::AtomicBool::new(false);
        assert_eq!(guarded_with(&broken, || None), 0);
        assert_eq!(guarded_with(&broken, || Some(90)), 90);
        assert_eq!(guarded_with(&broken, || panic!("broken zone")), 0);
        // Once broken, the zone is not read again.
        assert_eq!(guarded_with(&broken, || Some(90)), 0);
    }
}
